            # Hour, minute, second
            components[comp] = int(timestr[pos:pos + 2])
            pos += 2
            if has_sep and pos < len_str:
                if timestr[pos:pos + 1] == self._TIME_SEP:
                    pos += 1
                elif timestr[pos:pos + 1] in b'0123456789':
                    raise ValueError('Inconsistent use of ":" separator')

